import{_ as e,r as s,o,c as l,e as a,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Рендеринг представлений - October CMS - 3.x","titleTemplate":false,"description":"Узнайте, где хранится и отображается содержимое страниц.","frontmatter":{"subtitle":"Узнайте, где хранится и отображается содержимое страниц."},"headers":[{"level":2,"title":"Частичные представления","slug":"частичные-представления","link":"#частичные-представления","children":[{"level":3,"title":"Подсказки (Hint Partials)","slug":"подсказки-hint-partials","link":"#подсказки-hint-partials","children":[]},{"level":3,"title":"Проверка скрытия подсказок","slug":"проверка-скрытия-подсказок","link":"#проверка-скрытия-подсказок","children":[]}]},{"level":2,"title":"Макеты и дочерние макеты","slug":"макеты-и-дочерние-макеты","link":"#макеты-и-дочерние-макеты","children":[{"level":3,"title":"Форма с боковой панелью","slug":"форма-с-боковои-панелью","link":"#форма-с-боковои-панелью","children":[]}]},{"level":2,"title":"Расширение макета","slug":"расширение-макета","link":"#расширение-макета","children":[]}],"relativePath":"3.x/ru/extend/system/views.md","filePath":"3.x/ru/extend/system/views.md"}'),r={name:"3.x/ru/extend/system/views.md"};function u(k,n,d,g,h,m){const t=s("pre-heading"),p=s("post-heading");return o(),l("div",null,[a(t),n[0]||(n[0]=c("h1",null,"Рендеринг представлений",-1)),a(p),n[1]||(n[1]=i(`<p>Представления находятся в директории, имя которой совпадает с именем контроллера.</p><pre class="dir-container"><code><p>├── plugins
|   └── acme
|       └── blog
|           ├── controllers
|           |   ├── users  <em>← Директория представлений</em>
|           |   |   ├── <code>_partial.php</code>  <em>← Файл частичного представления</em>
|           |   |   └── <code>index.php</code>  <em>← Файл представления</em>
|           |   └── Users.php  <em>← Класс контроллера</em>
|           └── Plugin.php</p>
</code></pre><h2 id="частичные-представления"><a href="#частичные-представления" class="header-anchor">#</a> Частичные представления</h2><p>Частичные представления панели управления — это файлы с расширением <strong>php</strong>, расположенные в <a href="./controllers.html">директории представлений контроллера</a>. Имена файлов частичных представлений должны начинаться с подчёркивания: <strong>_partial.php</strong>. Частичные представления могут быть отрендерены со страницы панели управления или из другого частичного представления. Используйте метод контроллера <code>makePartial</code> для рендеринга частичного представления. Метод принимает два параметра — имя частичного представления и необязательный массив переменных для передачи. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;sidebar&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;showHeader&#39;</span> <span class="token operator">=&gt;</span> <span class="token constant boolean">true</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h3 id="подсказки-hint-partials"><a href="#подсказки-hint-partials" class="header-anchor">#</a> Подсказки (Hint Partials)</h3><p>Вы можете отображать информационные панели в панели управления, называемые подсказками, которые пользователь может скрыть. Первый параметр должен быть уникальным ключом для запоминания, была ли подсказка скрыта или нет. Второй параметр — это ссылка на частичное представление. Третий параметр может содержать дополнительные переменные для передачи в частичное представление, а также некоторые свойства подсказки.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;foo&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Вы также можете отключить возможность скрытия подсказки, установив значение ключа в null. Такая подсказка будет отображаться всегда:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeHintPartial</span><span class="token punctuation">(</span><span class="token constant">null</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;my_hint_partial&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Доступны следующие свойства:</p><div class="table"><table tabindex="0"><thead><tr><th>Свойство</th><th>Описание</th></tr></thead><tbody><tr><td><strong>type</strong></td><td>Устанавливает цвет подсказки, поддерживаемые типы: danger, info, success, warning. По умолчанию: info.</td></tr><tr><td><strong>title</strong></td><td>Добавляет раздел заголовка к подсказке.</td></tr><tr><td><strong>subtitle</strong></td><td>В дополнение к заголовку добавляет вторую строку в раздел заголовка.</td></tr><tr><td><strong>icon</strong></td><td>В дополнение к заголовку добавляет иконку в раздел заголовка.</td></tr></tbody></table></div><h3 id="проверка-скрытия-подсказок"><a href="#проверка-скрытия-подсказок" class="header-anchor">#</a> Проверка скрытия подсказок</h3><p>При использовании подсказок может быть полезно проверить, скрыл ли их пользователь. Это легко сделать с помощью метода <code>isBackendHintHidden</code>. Он принимает единственный параметр — уникальный ключ, указанный при первоначальном вызове <code>makeHintPartial</code>. Метод возвращает true, если подсказка была скрыта, и false в противном случае:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">isBackendHintHidden</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my_hint_key&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token comment">&lt;!-- Do something when the hint is hidden --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token keyword">endif</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><h2 id="макеты-и-дочерние-макеты"><a href="#макеты-и-дочерние-макеты" class="header-anchor">#</a> Макеты и дочерние макеты</h2><p>Макеты панели управления находятся в необязательной директории <strong>layouts/</strong> плагина. Пользовательский макет задаётся свойством <code>$layout</code> объекта контроллера. По умолчанию используется системный макет <code>default</code>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string layout to use for the view.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$layout</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;mycustomlayout&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Макеты также предоставляют возможность добавления пользовательских CSS-классов к тегу BODY. Это можно задать через свойство <code>$bodyClass</code> контроллера.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/**
 * @var string bodyClass (CSS) to add to the layout.
 */</span>
<span class="token keyword">public</span> <span class="token variable">$bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Для макета по умолчанию доступны следующие классы body:</p><ul><li><strong>compact-container</strong> — убирает отступы со всех сторон.</li><li><strong>slim-container</strong> — убирает отступы слева и справа.</li><li><strong>breadcrumb-flush</strong> — заставляет хлебные крошки страницы прилегать вплотную к элементу ниже.</li></ul><h3 id="форма-с-боковои-панелью"><a href="#форма-с-боковои-панелью" class="header-anchor">#</a> Форма с боковой панелью</h3><p>Макеты также могут использоваться подобно частичным представлениям, действуя как глобальное частичное представление. Система предоставляет пример <code>form-with-sidebar</code>, демонстрирующий новый способ реализации структуры дочерних макетов.</p><p>Перед использованием этого стиля макета убедитесь, что ваш контроллер использует класс body <code>compact-container</code>, установив его в методе действия контроллера или конструкторе.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">bodyClass</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;compact-container&#39;</span><span class="token punctuation">;</span>
</code></pre></div><p>Этот макет использует два заполнителя: область основного контента <strong>form-contents</strong> и дополнительную боковую панель <strong>form-sidebar</strong>. Пример:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">&lt;!-- Primary content --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-contents&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Main content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- Complimentary sidebar --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    Side content
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>

<span class="token comment">&lt;!-- Layout execution --&gt;</span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;body&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;class&#39;</span><span class="token operator">=&gt;</span><span class="token string single-quoted-string">&#39;layout stretch&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
        <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makeLayout</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;form-with-sidebar&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
    <span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token class-name static-context">Form</span><span class="token operator">::</span><span class="token function">close</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
<span class="token php language-php"><span class="token delimiter important">&lt;?php</span> <span class="token class-name static-context">Block</span><span class="token operator">::</span><span class="token function">endPut</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span>
</code></pre></div><p>Макет выполняется в последней секции путём переопределения заполнителя <strong>body</strong>, используемого каждым макетом панели управления. Он оборачивает всё HTML-тегом <code>&lt;form /&gt;</code> и рендерит дочерний макет <strong>form-with-sidebar</strong>. Этот файл расположен в <strong>modules/backend/layouts/form-with-sidebar.php</strong>.</p><h2 id="расширение-макета"><a href="#расширение-макета" class="header-anchor">#</a> Расширение макета</h2><p>Метод <code>fireViewEvent</code> используется в нескольких местах для <a href="./../extending.html">расширения области панели управления</a>. Событие <code>backend.layout.extendHead</code> может использоваться для расширения элемента head макета. Возвращаемое значение должно содержать разметку для включения. Следующий пример добавляет JavaScript-файл на каждую страницу панели управления.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.layout.extendHead&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;&lt;script src=&quot;/app/assets/js/myscript.js&quot;&gt;&lt;/script&gt;&#39;</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Контроллер доступен (первый аргумент) в событии, что можно использовать для таргетирования конкретных контроллеров. Следующий пример добавляет определённые CSS-стили только к контроллеру записей Tailor.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;backend.layout.extendHead&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$controller</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token variable">$controller</span> <span class="token keyword">instanceof</span> <span class="token class-name class-name-fully-qualified"><span class="token punctuation">\\</span>Tailor<span class="token punctuation">\\</span>Controllers<span class="token punctuation">\\</span>Entries</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">return</span> <span class="token string single-quoted-string">&#39;&lt;styles&gt; /* ... */ &lt;/styles&gt;&#39;</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,34))])}const y=e(r,[["render",u]]);export{v as __pageData,y as default};
